int checks=0;
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(20);}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full caller native-valid BEFORE Window");}
void same(const Session& a,const Session& b){check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Entire caller Session/native/History/preview/revision/generation unchanged");}
void write(const QString& path,const Document& d){QFile f(path);const auto b=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(b.data(),b.size())==static_cast<qint64>(b.size()),"Immutable actual or independent native retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error("Original visible source producer missing");}
void reveal(QWidget* c){QPointer<QWidget> alive=c;for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(alive&&alive->isVisible()&&alive->isEnabled(),"Original source producer survives reveal and is enabled");}

Document fixture(bool linked){auto d=empty_document("point-edit-document","comp","art");auto& board=d.compositions.front().artboards.front();board.width=640;board.height=480;for(const auto& id:{Id{"shape"},Id{"peer"},Id{"other"}}){Object object;object.id=id;object.name=id;object.source=default_primitive(id+"-source","nect.shape.rectangle");object.source->parameters.at("width").literal=80;object.source->parameters.at("height").literal=60;object.source->parameters.at("center_x").literal=id=="shape"?320:id=="peer"?180:460;object.source->parameters.at("center_y").literal=240;auto fill=default_operation(id+"-fill","nect.paint.fill");fill.parameters.at("r").literal=id=="shape"?1:0;fill.parameters.at("g").literal=id=="other"?1:0;fill.parameters.at("b").literal=id=="peer"?1:0;object.stack={fill};if(id!="other"){PointEdit correction;correction.id=id+"-source-point-edit";correction.enabled=id=="shape";correction.overrides[id+"-source-top-left"]["x"].literal=id=="shape"?285:145;object.point_edit=correction;}d.objects.emplace(id,object);d.compositions.front().roots.push_back(id);}if(linked)d.objects.at("shape").point_edit->enabled_driver=point_edit_enabled_ref("peer","peer-source-point-edit");return d;}
void flow(const QString& root,int mode){const bool expression=mode==4||mode==5,reset=mode==6||mode==7,link=mode==8||mode==9,unlink=mode>=10,success=mode==3||mode==5||mode==7||mode==9||mode==11,foreign_case=mode==0||mode==4||mode==6||mode==8||mode==10;auto initial=fixture(unlink);valid(initial);auto current=initial;current.objects.at("other").name="Current retained";valid(current);Session base(initial);base.apply({Rename{"other","Current retained"}},0);check(base.document()==current&&base.revision()==1,"Whole independent primitive/corrections/bypass/source/History before Window");auto foreign_initial=initial;foreign_initial.id="foreign-point-edit-document";foreign_initial.objects.at("shape").source->parameters.at("height").literal=90;foreign_initial.objects.at("shape").point_edit->overrides.at("shape-source-top-left").at("x").literal=290;foreign_initial.objects.at("peer").point_edit->enabled=true;valid(foreign_initial);auto foreign_current=foreign_initial;foreign_current.objects.at("other").name="Current retained";valid(foreign_current);Session foreign(foreign_initial);foreign.apply({Rename{"other","Current retained"}},0);check(foreign.document()==foreign_current&&foreign.revision()==base.revision()&&foreign.gesture_generation()==base.gesture_generation(),"Whole independent foreign correction/source with colliding stable IDs/counters before Window");auto busy=base;busy.begin_gesture(1);busy.update_gesture({Set{{"shape","","generator.height"},90}});auto preview=current;preview.objects.at("shape").source->parameters.at("height").literal=90;valid(preview);check(busy.document()==current&&busy.preview_document()==preview,"Whole independent active primitive preview before Window");auto transformed=current;const auto target=point_edit_enabled_ref("shape","shape-source-point-edit"),source=point_edit_enabled_ref("peer","peer-source-point-edit");if(reset)transformed.objects.at("shape").point_edit.reset();else if(expression)transformed.objects.at("shape").point_edit->enabled_expression=Expression{"false",1};else if(link)transformed.objects.at("shape").point_edit->enabled_driver=source;else if(unlink){transformed.objects.at("shape").point_edit->enabled_driver.reset();transformed.objects.at("shape").point_edit->enabled=false;}else transformed.objects.at("shape").point_edit->enabled=false;valid(transformed);auto committed=base;if(reset)committed.apply({ClearPointEdit{"shape"}},1);else if(expression)committed.apply({SetPointEditEnabledExpression{target,Expression{"false",1}}},1);else if(link)committed.apply({LinkPointEditEnabled{target,source}},1);else if(unlink)committed.apply({UnlinkPointEditEnabled{target}},1);else committed.apply({EnablePointEdit{"shape",false}},1);check(committed.document()==transformed,"Entire independent Point Edit semantic delta/source retention matches typed command before Window");auto history=committed;history.undo(2);check(history.document()==current,"Entire Point Edit Undo before Window");history.redo(3);check(history.document()==transformed&&history.history()==committed.history(),"One History/full Point Edit Redo before Window");auto expected=foreign_case?foreign:mode==2?busy:success?committed:base;const auto prefix=root+"/mode-"+QString::number(mode);write(prefix+"-expected.nect",expected.document());write(prefix+"-expected-preview.nect",expected.preview_document());
QSettings settings(prefix+"-settings.ini",QSettings::IniFormat);settings.setFallbacksEnabled(false);Window w(prefix+"-recovery",std::make_unique<FolderLibrary>(settings,FolderLibrary::PersistOverride{},FolderLibrary::ReadbackOverride{},prefix+"-assets"),&settings);w.host.session=base;w.host.edited();w.resize(1400,1150);w.show();events();w.canvas->set_active_artboard("comp","art",false);w.canvas->set_selection("shape","");events();auto* enabled=control<QCheckBox>(w,"point-edit-enabled");check(unlink?!enabled->isEnabled():enabled->isEnabled(),"Original checkbox follows literal/source-driven eligibility");if(!unlink)reveal(enabled);auto* driver=control<QToolButton>(w,"point-edit-enabled-driver");reveal(driver);check(driver->menu()&&driver->menu()->actions().size()==3,"Original Point Edit source actions present");QPointer<QWidget> actor=reset?static_cast<QWidget*>(control<QPushButton>(w,"point-edit-reset")):static_cast<QWidget*>(enabled);if(reset)reveal(actor);const auto original_host=w.host.session_id;QString callback_error,modal_status;bool refusal_open=false;int stages=0;
if(expression||link||reset)QTimer::singleShot(0,&w,[&]{try{auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget());if(mode==6&&!dialog){check(w.statusBar()->currentMessage().startsWith("SESSION_CONFLICT:"),"Stale reset refuses before opening another caller confirmation");return;}check(dialog,"Original Point Edit modal present");++stages;if(reset){auto* question=qobject_cast<QMessageBox*>(dialog);check(question&&question->windowTitle()=="Reset point edits"&&question->button(QMessageBox::Reset),"Original reset confirmation producer");check(dialog->grab().save(prefix+"-dialog.png"),"Actual reset confirmation before acceptance");question->button(QMessageBox::Reset)->click();}else{check(dialog->objectName()==(expression?"point-edit-enabled-expression-dialog":"point-edit-enabled-source-dialog"),"Original exact Point Edit expression/source dialog");if(expression){auto* draft=dialog->findChild<QPlainTextEdit*>("point-edit-enabled-expression-source");check(draft,"Original expression draft producer");draft->setPlainText("false");}else{auto* selector=dialog->findChild<QComboBox*>("point-edit-enabled-source-dialog-source");check(selector&&selector->count()==1&&selector->itemText(0).contains("peer-source-point-edit")&&selector->itemText(0).contains("peer"),"Original exact source correction Ref");selector->setCurrentIndex(0);}if(foreign_case)w.host.session=foreign;check(dialog->grab().save(prefix+"-dialog.png"),"Actual original source draft before Apply");auto* buttons=dialog->findChild<QDialogButtonBox*>();check(buttons&&buttons->button(QDialogButtonBox::Apply),"Original Point Edit Apply producer");buttons->button(QDialogButtonBox::Apply)->click();refusal_open=dialog->isVisible();if(refusal_open){auto* status=dialog->findChild<QLabel*>(expression?"point-edit-enabled-expression-status":"point-edit-enabled-source-dialog-status");check(status,"Original inline source refusal status");modal_status=status->text();check(dialog->grab().save(prefix+"-refusal.png"),"Actual retained draft/refusal before original Cancel");buttons->button(QDialogButtonBox::Cancel)->click();}}}catch(const std::exception& e){callback_error=QString::fromUtf8(e.what());if(auto* dialog=qobject_cast<QDialog*>(QApplication::activeModalWidget()))dialog->reject();}});
if(mode==0||mode==6||mode==10)w.host.session=foreign;else if(mode==1)w.host.session_id+="-changed";else if(mode==2)w.host.session=busy;if(expression)driver->menu()->actions().at(1)->trigger();else if(link)driver->menu()->actions().front()->trigger();else if(unlink)driver->menu()->actions().at(2)->trigger();else if(reset)qobject_cast<QPushButton*>(actor.data())->click();else enabled->click();events();check(callback_error.isEmpty(),"Original Point Edit action has no fixture exception");const auto observed=w.host.session;const auto window_status=w.statusBar()->currentMessage();const auto status=modal_status.isEmpty()?window_status:modal_status;write(prefix+"-observed.nect",observed.document());write(prefix+"-observed-preview.nect",observed.preview_document());check(w.grab().save(prefix+"-window.png"),"Actual entire Point Edit result before Save");QJsonObject v{{"mode",mode},{"status",status},{"window_status",window_status},{"modal_status",modal_status},{"refusal_open",refusal_open},{"modal_stages",stages},{"document_equal",observed.document()==expected.document()},{"preview_equal",observed.preview_document()==expected.preview_document()},{"history_equal",observed.history()==expected.history()},{"revision",qint64(observed.revision())},{"gesture_active",observed.gesture_active()},{"gesture_generation",qint64(observed.gesture_generation())},{"caller_identity_preserved",mode!=2||observed.gesture_identity()==busy.gesture_identity()},{"host_equal",mode==1?w.host.session_id!=original_host:w.host.session_id==original_host},{"view_equal",w.canvas->selected_object=="shape"&&w.canvas->selected_point.empty()&&w.canvas->active_composition()=="comp"&&w.canvas->active_artboard()=="art"},{"save_intent",mode!=2}};QFile metadata(prefix+"-producer.json");check(metadata.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Immutable entire Point Edit source/correction/History readback before Save");metadata.write(QJsonDocument(v).toJson());metadata.close();same(observed,expected);check(v["view_equal"].toBool()&&v["host_equal"].toBool()&&v["caller_identity_preserved"].toBool(),"Caller source view/gesture preserved");if(foreign_case||mode==1)check(status.startsWith("SESSION_CONFLICT:"),"Stale original Point Edit Document/Host refused explicitly");if(mode==2)check(status.startsWith("GESTURE_ACTIVE:"),"Active caller preserved by existing command refusal");if(mode==4||mode==8)check(refusal_open&&stages==1,"Source draft remains open on refusal before explicit Cancel");if(mode==6)check(stages==0,"Stale reset confirmation never targets new caller");if(success){w.host.session.undo(2);check(w.host.session.document()==current,"Actual whole Point Edit Undo");w.host.session.redo(3);check(w.host.session.document()==transformed,"Actual whole Point Edit Redo");w.host.session=observed;}if(mode!=2){w.host.save(prefix+"-saved.nect");w.host.flush();events();same(w.host.session,expected);check(read(prefix+"-saved.nect")==read(prefix+"-expected.nect")&&QFile::copy(prefix+"-saved.nect",prefix+"-snapshot.nect"),"Complete exact Point Edit native Save/snapshot, no normalization");}w.close();events();}
